//! Can a *catopt* language be assembled from data?
//!
//! Spike Q0 of `plan 0029` (catopt `project/plans/0029-handl-catopt-boundary-spike.md`):
//! catopt's bridge emits handl-shaped rows (`AstShapeDef`, `TransformDef`);
//! this test asserts that the **ten-file data layout** `language_from_dir`
//! reads can carry them — i.e. that catopt's vocabulary is expressible as
//! handl data, not merely *similar* to it.
//!
//! The fixture directory `tests/data/catopt-fragments/` is **generated by
//! catopt** (`lab/handl-spike/dump_fragments.py`, committed there) and
//! copied here verbatim: eight shell files (empty — catopt's "syntax" is
//! the IR, not a text language) plus `transforms.yaml`, carrying one
//! structural law (`assoc_add`) as a `TransformDef`.
//!
//! What this does and does not prove:
//!
//! * proves — the merge path accepts catopt's rows, the law lands in
//!   `lang.transforms` with its fields intact, and the folded `when`
//!   condition deserializes as `And([KindAt, ChildCount])`.
//! * does not prove — that a rewrite *fires* on a catopt term (that needs
//!   an AST, i.e. the next step of the spike), nor anything about tensor
//!   values (spike Q1).

use std::path::Path;

use handl_kit_data_canonical::language_from_dir;
use handl_language::TransformCondition;

fn fixture_dir() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/catopt-fragments")
}

#[test]
fn catopt_fragment_dir_assembles_a_language() {
    let lang = language_from_dir(&fixture_dir())
        .expect("catopt's fragment directory must merge into a Language");

    let ids: Vec<&str> = lang.transforms.iter().map(|d| d.id.as_str()).collect();
    assert!(
        ids.iter().any(|i| *i == "transform.catopt.assoc_add"),
        "expected catopt's law among {ids:?}"
    );
}

#[test]
fn catopt_law_survives_as_data() {
    let lang = language_from_dir(&fixture_dir()).expect("merges");
    let def = lang
        .transforms
        .get_by_id("transform.catopt.assoc_add")
        .expect("the law is retrievable by id");

    assert_eq!(def.pass, "catopt");
    assert_eq!(def.node_kind, "add");

    // `when` is ONE TransformCondition; catopt's clause list must have
    // folded into `And([...])` to deserialize at all.
    match def.when.as_ref().expect("when is present") {
        TransformCondition::And(parts) => assert_eq!(parts.len(), 2, "KindAt + ChildCount"),
        other => panic!("expected And([...]), got {other:?}"),
    }
}

// --- the full bank ---------------------------------------------------------

fn full_bank_dir() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/catopt-fragments-all")
}

/// The whole shipped bank (every rule), not the one-law slice.
///
/// This was written as a *pinned gap*: the bank used to fail to load
/// because a right-hand-side leaf had no `RewriteStep` counterpart
/// (`{"catopt:leaf": ...}` — a map where serde expects a tag) and because
/// handl's rule identity is `pass:node_kind:priority`, so many laws per
/// node kind collided.
///
/// Both are now closed on the producer's side — catopt maps a leaf to
/// `!Fresh` (an unbound pattern variable) or a `!Create` of a declared
/// `catopt:const` / `catopt:var` / `catopt:data` kind, and assigns
/// distinct priorities per `(pass, node_kind)` — so the bank loads and
/// this asserts success, with the count pinned so a silently dropped law
/// fails the test.
#[test]
fn catopt_full_bank_loads() {
    let lang = language_from_dir(&full_bank_dir())
        .expect("the whole catopt bank must assemble into a Language");
    let n = lang.transforms.iter().count();
    assert_eq!(n, 83, "every catopt law must land in lang.transforms");

    // The leaf kinds the bridge mints must be declared, or a rewrite that
    // creates one cannot be resolved by an engine.
    for kind in ["catopt:const", "catopt:var", "catopt:data"] {
        assert!(
            lang.ast.get_by_id(&format!("ast.{}", kind.replace(':', "."))).is_some(),
            "leaf shape for {kind} must be declared"
        );
    }
}

// --- step 1 of plan 0030: does a catopt law actually FIRE? ----------------
//
// Loading a `Language` is not running its engine.  This is the measurement
// plan 0030 gates the peer on: a catopt law, an AST shaped like a catopt
// term, and handl's `RewriteEngine` doing the rewrite.
//
// catopt's `assoc_add` says  add(a, add(b, c))  ->  add(add(a, b), c).
// Its emitted rule is `!Declarative { target_kind: add, children: [
// !Create { kind: add, children: [KeepPath([0]), KeepPath([1,0])] },
// KeepPath([1,1]) ] }` — i.e. rebuild the node as add(child0,
// child1.child0) with child1.child1 second — so the expected result is
// exactly the associativity law.

use handl_language::{Ast, AstNode, AstRef};
use handl_plugin_engine_transform_rewrite::RewriteEngine;

fn cnode(kind: &str, children: &[usize]) -> AstNode {
    AstNode::new(kind).with_payload(serde_json::json!({ "children": children }))
}

#[test]
fn catopt_law_fires_through_the_rewrite_engine() {
    let lang = language_from_dir(&fixture_dir()).expect("the slice loads");

    // add(a, add(b, c))
    let mut ast = Ast::new();
    ast.push(cnode("a", &[])); // 0
    ast.push(cnode("b", &[])); // 1
    ast.push(cnode("c", &[])); // 2
    ast.push(cnode("add", &[1, 2])); // 3 = add(b, c)
    ast.push(cnode("add", &[0, 3])); // 4 = add(a, add(b, c))

    let out = RewriteEngine::new()
        .apply_rule(&lang, &ast, AstRef::new(4), "transform.catopt.assoc_add")
        .expect("catopt's law must fire on a catopt-shaped term");

    assert_eq!(out.trace.rewrites.len(), 1, "exactly one rewrite");

    // Navigate the result: root add(_, _) with [add(a, b), c].
    let kids = |i: AstRef| -> Vec<AstRef> {
        out.ast
            .get(i)
            .expect("node")
            .payload
            .get("children")
            .and_then(|c| c.as_array())
            .expect("children")
            .iter()
            .map(|v| AstRef::new(v.as_u64().expect("index") as usize))
            .collect()
    };
    let root = out.root;
    assert_eq!(out.ast.get(root).unwrap().kind, "add");
    let top = kids(root);
    assert_eq!(top.len(), 2);

    let left = out.ast.get(top[0]).unwrap();
    assert_eq!(left.kind, "add", "left child is the new add(a, b)");
    let left_kids = kids(top[0]);
    assert_eq!(out.ast.get(left_kids[0]).unwrap().kind, "a");
    assert_eq!(out.ast.get(left_kids[1]).unwrap().kind, "b");
    assert_eq!(out.ast.get(top[1]).unwrap().kind, "c", "right child is c");
}
